    open_brackets = []
    open_parens = []
    open_brackets = []

    for char in s:
        if char == '(':
            open_parens.append(char)
        elif char == ')':
            if not open_parens:
                return False
            open_parens.pop()
        elif char == '[':
            open_brackets.append(char)
        elif char == ']':
            if not open_brackets:
