def formatear_bytes(n: int) -> str:
    """Convierte una cantidad de bytes a texto legible usando base 1024 y las unidades B, KB, MB, GB."""
    if n == 0:
        return "0 B"
    if n < 1024:
        return f"{n} B"
    if n < 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    if n < 1024 * 1024 * 1024:
        return f"{n / (1024 * 1024):.1f} MB"
    return f"{n / (1024 * 1024 * 1024):.1f} GB"

