    """Convierte un número de bytes a texto legible usando multiplos de 1024 y las unidades B, KB, MB, GB."""
    if n < 0:
        raise ValueError("El número de bytes no puede ser negativo.")
    if n == 0:
        return "0 B"

    unidad = "B"
    valor = n

    if valor >= 1024:
        valor = valor // 1024
        unidad = "KB"
    elif valor >= 1024:
        valor = valor // 1024
        unidad = "MB"
    elif valor >= 1024:
        valor = valor // 1024
        unidad = "GB"

    if valor == 1:
        return f"{valor} {unidad}"
    else:
        return f"{valor:.1f} {unidad}"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split('&'):
        if '=' in part:
            key, value = part.split('=', 1)
            result[key] = value
    return result

